256	fn last_user_message_text_from_body(body: &serde_json::Value) -> String {
257	    body["input"]
258	        .as_array()
259	        .expect("request input array")
260	        .iter()
261	        .filter(|item| item.get("role").and_then(serde_json::Value::as_str) == Some("user"))
262	        .filter_map(|item| item.get("content").and_then(serde_json::Value::as_array))
263	        .next_back()
264	        .expect("user message content")
265	        .iter()
266	        .filter(|span| span.get("type").and_then(serde_json::Value::as_str) == Some("input_text"))
267	        .filter_map(|span| span.get("text").and_then(serde_json::Value::as_str))
268	        .collect::<String>()
269	}
