74	pub(crate) struct GuardianRejectionCircuitBreaker {
75	    turns: std::collections::HashMap<String, GuardianRejectionCircuitBreakerTurn>,
76	}
77	
78	#[derive(Debug, Default)]
79	struct GuardianRejectionCircuitBreakerTurn {
80	    consecutive_denials: u32,
81	    total_denials: u32,
82	    interrupt_triggered: bool,
83	}
84	
85	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
86	pub(crate) enum GuardianRejectionCircuitBreakerAction {
87	    Continue,
88	    InterruptTurn {
89	        consecutive_denials: u32,
90	        total_denials: u32,
91	    },
92	}
93	
94	impl GuardianRejectionCircuitBreaker {
95	    pub(crate) fn clear_turn(&mut self, turn_id: &str) {
96	        self.turns.remove(turn_id);
97	    }
98	
99	    pub(crate) fn record_denial(&mut self, turn_id: &str) -> GuardianRejectionCircuitBreakerAction {
100	        let turn = self.turns.entry(turn_id.to_string()).or_default();
101	        turn.consecutive_denials = turn.consecutive_denials.saturating_add(1);
102	        turn.total_denials = turn.total_denials.saturating_add(1);
103	        if !turn.interrupt_triggered
104	            && (turn.consecutive_denials >= MAX_CONSECUTIVE_GUARDIAN_DENIALS_PER_TURN
105	                || turn.total_denials >= MAX_TOTAL_GUARDIAN_DENIALS_PER_TURN)
106	        {
107	            turn.interrupt_triggered = true;
108	            GuardianRejectionCircuitBreakerAction::InterruptTurn {
109	                consecutive_denials: turn.consecutive_denials,
110	                total_denials: turn.total_denials,
111	            }
112	        } else {
113	            GuardianRejectionCircuitBreakerAction::Continue
114	        }
115	    }
116	
117	    pub(crate) fn record_non_denial(&mut self, turn_id: &str) {
118	        let turn = self.turns.entry(turn_id.to_string()).or_default();
119	        turn.consecutive_denials = 0;
120	    }
121	}
